#!/usr/bin/env node
/*
 * One-shot commands against the BTP destinations through btp-proxy.js (cf ssh tunnel).
 *
 *   node scripts/btp.js start <env>          run the app (fiori run, ui5-btp-<env>.yaml) via BTP_DESTINATION
 *   node scripts/btp.js deploy <env>         build + deploy (ui5-deploy-btp-<env>.yaml) via BTP_DEPLOY_DESTINATION
 *   node scripts/btp.js deploy <env> --test  same, in test mode
 *
 * Settings come from .env.<env> (generated by @scodigis/generator-btp-on-premise-scripts, one per environment such
 * as dev / qual, see btp-env.js); <env> may be left out when the project has only one. cf is pointed at the
 * environment's API endpoint / org / space first (cf login in the terminal when needed). Each destination gets its own
 * proxy: BTP_PROXY_PORT / BTP_TUNNEL_PORT (5050 / 20003) for the runtime one, BTP_DEPLOY_PROXY_PORT /
 * BTP_DEPLOY_TUNNEL_PORT (5051 / 20004) for the deploy one; both share the runtime ports when they are
 * the same destination.
 *
 * Proxy handling: a btp-proxy already answering on the port for the same destination is reused.
 * Otherwise a btp-proxy / cf ssh tunnel left on those ports is stopped and a proxy is started;
 * a proxy started here is stopped again when the command ends (Ctrl+C included).
 */
const { spawn, execFileSync } = require("child_process");
const fs = require("fs");
const http = require("http");
const path = require("path");

const { ROOT, loadProfile, ensureCfTarget } = require("./btp-env");

const isWin = process.platform === "win32";
const log = (msg) => console.log(`[btp] ${msg}`);

const [mode, ...rest] = process.argv.slice(2);
const flags = rest.filter((a) => a.startsWith("--"));
if (!["start", "deploy"].includes(mode)) {
	console.error("usage: node scripts/btp.js start | deploy [<env>] [--test]");
	process.exit(1);
}
let profile;
try {
	profile = loadProfile(rest.find((a) => !a.startsWith("--")));
} catch (e) {
	console.error(`[btp] ${e.message}`);
	process.exit(1);
}
const suffix = profile ? `-${profile}` : "";

const env = process.env;
const runtime = {
	destination: env.BTP_DESTINATION,
	port: Number(env.BTP_PROXY_PORT || 5050),
	tunnelPort: Number(env.BTP_TUNNEL_PORT || 20003)
};
const deployDestination = env.BTP_DEPLOY_DESTINATION || runtime.destination;
const proxyConfig = mode === "start" || deployDestination === runtime.destination
	? runtime
	: { destination: deployDestination, port: Number(env.BTP_DEPLOY_PROXY_PORT || 5051), tunnelPort: Number(env.BTP_DEPLOY_TUNNEL_PORT || 20004) };
if (!env.BTP_APP || !proxyConfig.destination) {
	console.error(`[btp] BTP_APP and BTP_DESTINATION must be set (${profile ? `.env.${profile}` : ".env"}) - run the 'BTP On-Premise Access' generator again`);
	process.exit(1);
}

function proxyHealth(port) {
	return new Promise((resolve) => {
		const req = http.get({ host: "127.0.0.1", port, path: "/__btp-proxy/health", timeout: 3000 }, (res) => {
			let body = "";
			res.on("data", (c) => (body += c));
			res.on("end", () => {
				try { resolve(res.statusCode === 200 ? JSON.parse(body) : "foreign"); } catch (e) { resolve("foreign"); }
			});
		});
		req.on("timeout", () => req.destroy());
		req.on("error", () => resolve(undefined));
	});
}

// [{ pid, command }] of the processes listening on a local port
function listeners(port) {
	try {
		if (isWin) {
			const ps = `Get-NetTCPConnection -LocalPort ${port} -State Listen -ErrorAction SilentlyContinue | Select-Object -ExpandProperty OwningProcess -Unique | ForEach-Object { $p = Get-CimInstance Win32_Process -Filter "ProcessId=$_"; "$_|$($p.CommandLine)" }; exit 0`;
			return execFileSync("powershell", ["-NoProfile", "-Command", ps], { encoding: "utf8" })
				.split(/\r?\n/).filter(Boolean).map((l) => ({ pid: Number(l.split("|")[0]), command: l.slice(l.indexOf("|") + 1) }));
		}
		return execFileSync("lsof", ["-nP", `-iTCP:${port}`, "-sTCP:LISTEN", "-t"], { encoding: "utf8" })
			.split(/\s+/).filter(Boolean).map((pid) => ({
				pid: Number(pid),
				command: execFileSync("ps", ["-o", "command=", "-p", pid], { encoding: "utf8" }).trim()
			}));
	} catch (e) {
		return []; // lsof exits 1 when nothing listens
	}
}

const ours = (command) => /btp-proxy\.js/.test(command) || /\bssh\b.*\s-L\s/.test(command);

async function stopStale({ port, tunnelPort }) {
	for (const p of [port, tunnelPort]) {
		for (const { pid, command } of listeners(p)) {
			if (!ours(command)) {
				throw new Error(`port ${p} is used by another program (pid ${pid}: ${command || "unknown"}) - free it or change the port in .env`);
			}
			if (isWin) {
				try { execFileSync("taskkill", ["/pid", String(pid), "/T", "/F"], { stdio: "ignore" }); } catch (e) { /* gone */ }
			} else {
				try { process.kill(pid, "SIGTERM"); } catch (e) { /* gone */ }
			}
			log(`stopped stale proxy/tunnel on :${p} (pid ${pid})`);
		}
	}
	for (let i = 0; i < 20 && (listeners(port).length || listeners(tunnelPort).length); i++) {
		await new Promise((r) => setTimeout(r, 250));
	}
}

const children = [];
// Windows needs a shell for npm / .cmd files; the command line is built here (spawn with shell + args is deprecated)
const quote = (arg) => (/^[\w\-.\/\\:=@]+$/.test(arg) ? arg : `"${arg.replace(/"/g, '""')}"`);
function run(cmd, args, options = {}) {
	const shell = options.shell === undefined ? isWin : options.shell;
	const child = shell
		? spawn([cmd, ...args].map(quote).join(" "), { cwd: ROOT, stdio: "inherit", ...options, shell })
		: spawn(cmd, args, { cwd: ROOT, stdio: "inherit", ...options, shell });
	children.push(child);
	return child;
}

// the project's own fiori CLI - npx would otherwise try to download a non-existent "fiori" package
function fioriCli() {
	const bin = path.join(ROOT, "node_modules", ".bin", isWin ? "fiori.cmd" : "fiori");
	if (!fs.existsSync(bin)) {
		throw new Error("the fiori CLI (@sap/ux-ui5-tooling) is not installed in this project - run 'npm install' first");
	}
	return bin;
}

function killTree(child) {
	if (child.exitCode !== null || child.signalCode !== null) return;
	if (isWin) {
		try { execFileSync("taskkill", ["/pid", String(child.pid), "/T", "/F"], { stdio: "ignore" }); } catch (e) { /* gone */ }
	} else {
		child.kill("SIGINT");
	}
}

let stopping = false;
function finish(code) {
	if (stopping) return;
	stopping = true;
	children.forEach(killTree);
	process.exit(code);
}
process.on("SIGINT", () => finish(130));
process.on("SIGTERM", () => finish(143));

function startProxy({ destination, port, tunnelPort }) {
	return new Promise((resolve, reject) => {
		const args = [path.join(__dirname, "btp-proxy.js"), ...(profile ? ["--profile", profile] : []), "--destination", destination, "--port", String(port), "--tunnel-port", String(tunnelPort)];
		const proxy = run(process.execPath, args, { shell: false, stdio: ["ignore", "pipe", "inherit"] });
		let ready = false;
		proxy.stdout.on("data", (chunk) => {
			process.stdout.write(chunk);
			if (!ready && /\[btp-proxy\] listening on/.test(chunk.toString())) {
				ready = true;
				resolve(proxy);
			}
		});
		proxy.on("exit", (code) => {
			if (!ready) return reject(new Error(`proxy exited during startup (${code}) - are you logged in with 'cf login'?`));
			if (!stopping) {
				console.error(`[btp] proxy exited (${code}), stopping`);
				finish(code || 1);
			}
		});
	});
}

async function ensureProxy(config) {
	const health = await proxyHealth(config.port);
	// a destination name can exist in several subaccounts - the environment and app must match too
	if (health && health !== "foreign" && health.destination === config.destination && health.app === env.BTP_APP && (health.profile || undefined) === profile) {
		log(`reusing running proxy on :${config.port} (destination ${health.destination})`);
		return;
	}
	if (health === "foreign") log(`port ${config.port} is taken by something that is not a current btp-proxy, replacing it`);
	else if (health) log(`proxy on :${config.port} serves destination ${health.destination}${health.profile ? ` (${health.profile})` : ""}, replacing it with ${config.destination}${profile ? ` (${profile})` : ""}`);
	await stopStale(config);
	// the proxy reads the app's bindings and opens cf ssh in the targeted space - a cf login can only run here, in the terminal
	ensureCfTarget({ interactive: true, log });
	log(`starting proxy for destination ${config.destination} on :${config.port}...`);
	await startProxy(config);
}

const exitWith = (child) => new Promise((resolve) => child.on("exit", (code) => resolve(code === null ? 1 : code)));

async function main() {
	const fiori = fioriCli();
	await ensureProxy(proxyConfig);

	if (mode === "start") {
		// open the same page as the project's own "start" script
		let open = "test/flp.html#app-preview";
		try {
			const start = require(path.join(ROOT, "package.json")).scripts.start || "";
			const m = /--open\s+(?:"([^"]+)"|'([^']+)'|(\S+))/.exec(start);
			if (m) open = m[1] || m[2] || m[3];
		} catch (e) { /* keep the default */ }
		finish(await exitWith(run(fiori, ["run", "--config", `./ui5-btp${suffix}.yaml`, "--open", open])));
		return;
	}

	// deploy - USR / SAP_PWD from .env.<env> reach fiori deploy through the inherited environment
	const deployConfig = `ui5-deploy-btp${suffix}.yaml`;
	if (!fs.existsSync(path.join(ROOT, deployConfig))) throw new Error(`${deployConfig} not found - deployment is not set up for this environment, run the generator again`);
	const build = await exitWith(run("npm", ["run", "build"]));
	if (build !== 0) return finish(build);
	const deployArgs = ["deploy", "-y", "--config", deployConfig];
	if (flags.includes("--test")) deployArgs.push("--testMode", "true");
	finish(await exitWith(run(fiori, deployArgs)));
}

main().catch((err) => {
	console.error(`[btp] ${err.message}`);
	finish(1);
});
